// Package catalogbench populates the catalog with synthetic objects, for
// listing tests and the catalog benchmark. Rows are generated by
// PostgreSQL itself (generate_series), one bounded batch per transaction,
// so populating millions of objects holds no more than one batch's
// statement in memory on either side. No object bytes exist for these
// records: they measure the catalog, never storage.
package catalogbench

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

// Spec describes a synthetic catalog.
type Spec struct {
	TenantID string
	// Objects are numbered From to From+Objects-1, so a catalog can grow
	// in steps.
	From    int64
	Objects int64
	// VersionsPerObject published versions each; the last is current.
	VersionsPerObject int
	// Datasets spreads objects over this many dataset namespaces ("ds-N");
	// 1 keeps them all in the root namespace.
	Datasets  int
	BatchSize int64
	// Base is the newest timestamp; objects get older with their number.
	// Updated times repeat every 1000 objects, so time-ordered listings
	// have ties to break.
	Base time.Time
}

// Paths are "<area>/<year>/file-<n>.txt" with area one of photos, docs,
// videos, logs (n%4) and year 2020 to 2025 (2020 + n%6). The namespace,
// metadata ({"camera": "c0".."c9", "batch": "0".."99"}), content type
// and size come from hashes of n, so they are independent of path order,
// as a filter usually is.
const (
	objectsSQL = `
		INSERT INTO catalog_objects (id, tenant_id, dataset, path, path_key, next_version, metadata, created_by, created_at, updated_at)
		SELECT format('obj-%s-%s', $1::text, i), $1,
		       CASE WHEN $4 > 1 THEN 'ds-' || (abs(hashint8(i + 1)::bigint) % $4) ELSE '' END,
		       g.path, lower(g.path), $5 + 1,
		       jsonb_build_object('camera', 'c' || (abs(hashint8(i + 2)::bigint) % 10), 'batch', (abs(hashint8(i + 3)::bigint) % 100)::text),
		       'catalog-bench', $6::timestamptz - make_interval(secs => i), $6::timestamptz - make_interval(secs => i % 1000)
		FROM (SELECT i, format('%s/%s/file-%s.txt', (ARRAY['photos','docs','videos','logs'])[1 + i % 4], 2020 + i % 6,
		                      lpad(i::text, 9, '0')) AS path
		      FROM generate_series($2::bigint, $3::bigint - 1) AS i) AS g`

	sessionsSQL = `
		INSERT INTO upload_sessions (id, tenant_id, owner_id, object_key, file_name, content_type, expected_size, status,
		                             expires_at, created_at, updated_at, path, object_id, dataset)
		SELECT format('up-%s-%s-%s', $1::text, i, v), $1, 'catalog-bench', format('quarantine/%s/up-%s-%s', $1::text, i, v),
		       format('file-%s.txt', i), (ARRAY['text/plain','image/jpeg','video/mp4'])[1 + abs(hashint8(i + 4)::bigint) % 3],
		       1000 + abs(hashint8(i + 5)::bigint) % 100000 + v,
		       'VERIFIED', $6::timestamptz + interval '1 day', $6::timestamptz - make_interval(secs => i), $6::timestamptz,
		       format('file-%s.txt', i), format('obj-%s-%s', $1::text, i),
		       CASE WHEN $4 > 1 THEN 'ds-' || (abs(hashint8(i + 1)::bigint) % $4) END
		FROM generate_series($2::bigint, $3::bigint - 1) AS i, generate_series(1, $5) AS v`

	assetsSQL = `
		INSERT INTO assets (id, tenant_id, owner_id, upload_id, object_key, file_name, content_type, size_bytes, status,
		                    created_at, updated_at, published_at, object_id, version, dataset)
		SELECT format('ast-%s-%s-%s', $1::text, i, v), $1, 'catalog-bench', format('up-%s-%s-%s', $1::text, i, v),
		       format('published/%s/ast-%s-%s-%s', $1::text, $1::text, i, v), format('file-%s.txt', i),
		       (ARRAY['text/plain','image/jpeg','video/mp4'])[1 + abs(hashint8(i + 4)::bigint) % 3], 1000 + abs(hashint8(i + 5)::bigint) % 100000 + v,
		       'AVAILABLE',
		       $6::timestamptz - make_interval(secs => i), $6::timestamptz, $6::timestamptz - make_interval(secs => i % 1000),
		       format('obj-%s-%s', $1::text, i), v,
		       CASE WHEN $4 > 1 THEN 'ds-' || (abs(hashint8(i + 1)::bigint) % $4) END
		FROM generate_series($2::bigint, $3::bigint - 1) AS i, generate_series(1, $5) AS v`

	currentSQL = `
		UPDATE catalog_objects AS o
		SET current_asset_id = a.id, current_version = a.version, size_bytes = a.size_bytes,
		    content_type = a.content_type, published_at = a.published_at
		FROM assets AS a
		WHERE o.tenant_id = $1 AND a.tenant_id = $1 AND a.object_id = o.id AND a.version = $4
		  AND o.id IN (SELECT format('obj-%s-%s', $1::text, i) FROM generate_series($2::bigint, $3::bigint - 1) AS i)`
)

// Result is what populating took.
type Result struct {
	Objects  int64
	Versions int64
	Batches  int
	Duration time.Duration
}

// Populate inserts the spec's objects, their upload sessions and their
// versions, batch by batch. progress, when set, is called after each
// batch (for memory sampling and progress output).
func Populate(ctx context.Context, pool *pgxpool.Pool, spec Spec, progress func(done int64)) (Result, error) {
	if spec.TenantID == "" || spec.Objects <= 0 || spec.VersionsPerObject <= 0 || spec.BatchSize <= 0 {
		return Result{}, errors.New("tenant, objects, versions per object and batch size are required")
	}
	if spec.Datasets <= 0 {
		spec.Datasets = 1
	}
	if spec.Base.IsZero() {
		spec.Base = time.Now().UTC()
	}
	started := time.Now()
	var res Result
	for lo := spec.From; lo < spec.From+spec.Objects; lo += spec.BatchSize {
		hi := min(lo+spec.BatchSize, spec.From+spec.Objects)
		tx, err := pool.Begin(ctx)
		if err != nil {
			return res, err
		}
		rows := []any{spec.TenantID, lo, hi, spec.Datasets, spec.VersionsPerObject, spec.Base}
		for _, step := range []struct {
			sql  string
			args []any
		}{
			{objectsSQL, rows}, {sessionsSQL, rows}, {assetsSQL, rows},
			{currentSQL, []any{spec.TenantID, lo, hi, spec.VersionsPerObject}},
		} {
			if _, err := tx.Exec(ctx, step.sql, step.args...); err != nil {
				_ = tx.Rollback(ctx)
				return res, fmt.Errorf("populate objects %d-%d: %w", lo, hi, err)
			}
		}
		if err := tx.Commit(ctx); err != nil {
			return res, err
		}
		res.Batches++
		res.Objects += hi - lo
		res.Versions += (hi - lo) * int64(spec.VersionsPerObject)
		if progress != nil {
			progress(res.Objects)
		}
	}
	res.Duration = time.Since(started)
	return res, nil
}

// Remove deletes a synthetic tenant's catalog, sessions and versions, in
// batches.
func Remove(ctx context.Context, pool *pgxpool.Pool, tenantID string) error {
	for _, q := range []string{
		`UPDATE catalog_objects SET current_asset_id = NULL, current_version = NULL WHERE tenant_id = $1`,
		`DELETE FROM assets WHERE tenant_id = $1`,
		`DELETE FROM upload_sessions WHERE tenant_id = $1`,
		`DELETE FROM catalog_objects WHERE tenant_id = $1`,
	} {
		if _, err := pool.Exec(ctx, q, tenantID); err != nil {
			return err
		}
	}
	return nil
}
